<?php namespace App\Services; class ScoreClienteService { public function score(array $cliente,array $lancamentos,array $pagamentos):array { $open=array_filter($lancamentos,fn($l)=>$l['status']!=='cancelado'); $late=collect($open)->filter(fn($l)=>($l['data_vencimento']??'') < today()->toDateString())->count(); $balance=collect($open)->sum('valor')-collect($pagamentos)->sum('valor'); if(!count($lancamentos)) return ['cinza','Cliente novo, ainda sem histórico suficiente.']; if($late && collect($open)->min('data_vencimento') < today()->subDays(15)->toDateString() || $balance > (float)($cliente['limite_fiado']??0)) return ['vermelho','Cliente ultrapassou o limite ou possui atraso relevante.']; if($late) return ['amarelo','Cliente está com atraso.']; if(count($pagamentos)) return ['verde','Cliente costuma pagar em dia.']; return ['cinza','Cliente novo, ainda sem histórico suficiente.']; } }
